import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for concatenation of two tensors along the channel dimension
cat_2tensors_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void cat_2tensors_kernel(const float* x, const float* y, float* out,
                                    const int bs, const int c1, const int c2,
                                    const int h, const int w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = bs * (c1 + c2) * h * w;
    if (idx < total_size) {
        int hw = h * w;
        int out_c = (idx / hw) % (c1 + c2);
        int out_n = idx / ((c1 + c2) * hw);
        int out_hw = idx % hw;
        if (out_c < c1) {
            // Copy from x
            out[idx] = x[out_n * c1 * hw + out_c * hw + out_hw];
        } else {
            // Copy from y
            int y_c = out_c - c1;
            out[idx] = y[out_n * c2 * hw + y_c * hw + out_hw];
        }
    }
}

torch::Tensor cat_2tensors_cuda(torch::Tensor x, torch::Tensor y) {
    // We assume x and y have the same (N, C, H, W) layout except for C.
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(y.is_cuda(), "y must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4 && y.dim() == 4, "Tensors must be 4D");

    int bs = x.size(0);
    int c1 = x.size(1);
    int h = x.size(2);
    int w = x.size(3);
    int c2 = y.size(1);
    TORCH_CHECK(h == y.size(2) && w == y.size(3),
                "Spatial dimensions of x and y must match");

    auto out_shape = std::vector<int64_t>{bs, c1 + c2, h, w};
    auto out = torch::empty(out_shape, x.options());

    int block_size = 256;
    int total_size = bs * (c1 + c2) * h * w;
    int grid_size = (total_size + block_size - 1) / block_size;

    cat_2tensors_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        out.data_ptr<float>(),
        bs, c1, c2, h, w
    );
    return out;
}
"""

cat_2tensors_cpp_source = r"""
torch::Tensor cat_2tensors_cuda(torch::Tensor x, torch::Tensor y);
"""

# Build the custom operator
cat_2tensors = load_inline(
    name="cat_2tensors",
    cpp_sources=cat_2tensors_cpp_source,
    cuda_sources=cat_2tensors_source,
    functions=["cat_2tensors_cuda"],
    verbose=False,
    extra_cflags=[],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    def __init__(self, num_layers: int, num_input_features: int, growth_rate: int):
        """
        :param num_layers: The number of layers in the dense block
        :param num_input_features: The number of input feature maps
        :param growth_rate: The growth rate for the dense block (new features added per layer)
        """
        super(ModelNew, self).__init__()
        layers = []
        for i in range(num_layers):
            layers.append(self._make_layer(num_input_features + i * growth_rate, growth_rate))
        self.layers = nn.ModuleList(layers)

        # Reference to the custom cat operator
        self.custom_cat = cat_2tensors

    def _make_layer(self, in_features: int, growth_rate: int):
        """
        Creates a single layer with BatchNorm, ReLU, Conv2D, and Dropout.
        """
        return nn.Sequential(
            nn.BatchNorm2d(in_features),
            nn.ReLU(inplace=True),
            nn.Conv2d(in_features, growth_rate, kernel_size=3, padding=1, bias=False),
            nn.Dropout(0.0)
        )

    def forward(self, x):
        """
        :param x: Input tensor of shape (batch_size, num_input_features, height, width)
        :return: Concatenated output tensor (batch_size, num_output_features, height, width)
        """
        features = [x]
        for layer in self.layers:
            new_feature = layer(x)
            features.append(new_feature)
            # Use the custom CUDA operator to concatenate along the channel dimension
            x = self.custom_cat.cat_2tensors_cuda(x, new_feature)
        return x
